<?php require __DIR__.'/includes/bootstrap.php';
$query=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$sort=(string)($_GET['sort']??'newest');$products=array_values(shop_catalog());
if($category) $products=array_filter($products,fn($p)=>strcasecmp($p['category'],$category)===0);if($query)$products=array_filter($products,function($p)use($query){$needle=mb_strtolower($query);return str_contains(mb_strtolower($p['name'].' '.$p['short_description'].' '.$p['category']),$needle);});
usort($products,function($a,$b)use($sort){if($sort==='price-asc')return $a['price']<=>$b['price'];if($sort==='price-desc')return $b['price']<=>$a['price'];return strcmp((string)$b['created_at'],(string)$a['created_at']);});
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shop Artefacts & Trinkets | TraveL Den</title><meta name="description" content="Browse physical travel artefacts, souvenirs and trinkets in Kenyan Shillings."><link rel="canonical" href="/shop/products.php"><link rel="stylesheet" href="/shop/assets/css/shop.css"></head><body><?php require __DIR__.'/includes/header.php'; ?>
<p class="sample-banner">Demonstration catalogue — these sample products are not real offers until replaced with the verified product catalogue.</p><h1>Physical artefacts and trinkets</h1>
<form class="shop-controls" method="get"><label>Search<input type="search" name="q" value="<?= shop_e($query) ?>" placeholder="Search products"></label><label>Category<select name="category"><option value="">All categories</option><?php foreach(shop_category_list() as $c): ?><option value="<?= shop_e($c) ?>" <?= $category=== $c?'selected':'' ?>><?= shop_e($c) ?></option><?php endforeach;?></select></label><label>Sort<select name="sort"><option value="newest" <?= $sort==='newest'?'selected':'' ?>>Newest</option><option value="price-asc" <?= $sort==='price-asc'?'selected':'' ?>>Price: low to high</option><option value="price-desc" <?= $sort==='price-desc'?'selected':'' ?>>Price: high to low</option></select></label></form>
<p aria-live="polite"><?= count($products) ?> <?= count($products)===1?'product':'products' ?> found</p><div class="shop-grid"><?php foreach($products as $product): ?><article class="product-card"><a href="/shop/product.php?id=<?= urlencode($product['id']) ?>"><img src="<?= shop_e($product['main_image']) ?>" alt="<?= shop_e($product['name']) ?>" loading="lazy"></a><div class="product-card-body"><h2><a href="/shop/product.php?id=<?= urlencode($product['id']) ?>"><?= shop_e($product['name']) ?></a></h2><p><?= shop_e($product['short_description']) ?></p><p class="price"><?= shop_money($product['price']) ?> <small>KES</small></p><p class="stock <?= $product['stock']<=0?'out':'' ?>"><?= $product['stock']>0 ? (int)$product['stock'].' in stock':'Out of stock' ?></p><?php if($product['stock']>0): ?><form method="post" action="/shop/cart.php"><input type="hidden" name="action" value="add"><input type="hidden" name="id" value="<?= shop_e($product['id']) ?>"><?= csrf_field() ?><button class="shop-button" type="submit">Add to cart</button></form><?php endif;?></div></article><?php endforeach;?></div>
<?php require __DIR__.'/includes/footer.php'; ?></body></html>
